/// A content block of an open: the actor's (kind 0), a stably named subobject (1: name, checksum) or a dynamic one (2: its class chain).
struct Block {
    const char* cls;      // the schema class that reads the payload
    int         kind;
    bool        rep;      // the payload starts with a RepLayout block
    uint32_t    payload;  // into kPayloads
    const char* name;
    uint32_t    checksum;
    uint32_t    class_chain;   // into kChains (kind 2)
};

